fn numpy_insert<T>(arr: Vec<T>, idx: usize, value: T) -> Vec<T> {
    let mut result = Vec::with_capacity(arr.len() + 1);

    // Push all elements before idx
    for i in 0..idx {
        // Using `get` is safe here since idx <= arr.len()
        // and therefore i < idx <= arr.len()
        result.push(arr[i].to_owned());
    }

    // Insert the new value at idx
    result.push(value);

    // Push all elements from idx to end shifted by one position
    for i in idx..arr.len() {
        result.push(arr[i].to_owned());
    }

    result
}